// ============================================================
// OUTPUT DISPATCHER
// Fans out to all 4 output channels simultaneously after
// sheets are updated. Reads contact details from payload
// (passed in from Master Sheet via Orchestrator).
// ============================================================
const d = $input.first().json;

const statusEmoji = {
  'Blocked': '🔴',
  'On Track': '🟡',
  'Completed': '🟢'
}[d.status] || '⚪';

const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

// --- 1. SUPERVISOR ACKNOWLEDGEMENT (WhatsApp) ---
const supervisorAck = `✅ Update Received!

Hi ${d.supervisor_name || 'Supervisor'},
Your report for *Site ${d.site_id || 'N/A'}* has been logged successfully.

📊 Status: ${statusEmoji} ${d.status}
📈 Progress: ${d.progress_pct || 'N/A'}%
🕐 Logged at: ${now}

Thank you. Keep up the good work! 💪`;

// --- 2. MANAGER WHATSAPP SUMMARY ---
const managerWhatsApp = `📋 *SITE UPDATE — ${d.site_id || 'Unknown Site'}*

${statusEmoji} *Status:* ${d.status}
📈 *Progress:* ${d.progress_pct || 'N/A'}%
🔧 *Phase:* ${d.work_phase || 'N/A'}
👷 *Supervisor:* ${d.supervisor_name || 'N/A'}

📝 *Work Done:*
${d.raw_text || 'No details provided'}

${d.blockers ? '⚠️ *Blockers:* ' + d.blockers : '✅ No blockers'}
${d.next_steps ? '➡️ *Next Steps:* ' + d.next_steps : ''}

🕐 ${now}`;

// --- 3. RAHUL TANWAR EOD SUMMARY (Email body) ---
const rahulEmailSubject = `[Genome] Site ${d.site_id || 'N/A'} — ${d.status} | ${new Date().toLocaleDateString('en-IN')}`;
const rahulEmailBody = `
<html><body style='font-family:Arial,sans-serif;max-width:600px;margin:auto;'>
<h2 style='color:#1a1a2e;border-bottom:2px solid #e94560;padding-bottom:8px;'>
  📊 Site Status Summary — ${d.site_id || 'N/A'}
</h2>
<table style='width:100%;border-collapse:collapse;margin:16px 0;'>
  <tr style='background:#f0f0f0;'><th style='padding:8px;text-align:left;'>Field</th><th style='padding:8px;text-align:left;'>Details</th></tr>
  <tr><td style='padding:8px;border-bottom:1px solid #ddd;'><b>Site ID</b></td><td style='padding:8px;border-bottom:1px solid #ddd;'>${d.site_id || 'N/A'}</td></tr>
  <tr><td style='padding:8px;border-bottom:1px solid #ddd;'><b>Status</b></td><td style='padding:8px;border-bottom:1px solid #ddd;'>${statusEmoji} ${d.status}</td></tr>
  <tr><td style='padding:8px;border-bottom:1px solid #ddd;'><b>Progress</b></td><td style='padding:8px;border-bottom:1px solid #ddd;'>${d.progress_pct || 'N/A'}%</td></tr>
  <tr><td style='padding:8px;border-bottom:1px solid #ddd;'><b>Phase</b></td><td style='padding:8px;border-bottom:1px solid #ddd;'>${d.work_phase || 'N/A'}</td></tr>
  <tr><td style='padding:8px;border-bottom:1px solid #ddd;'><b>Supervisor</b></td><td style='padding:8px;border-bottom:1px solid #ddd;'>${d.supervisor_name || 'N/A'}</td></tr>
  <tr><td style='padding:8px;border-bottom:1px solid #ddd;'><b>Work Done Today</b></td><td style='padding:8px;border-bottom:1px solid #ddd;'>${d.raw_text || 'N/A'}</td></tr>
  <tr><td style='padding:8px;border-bottom:1px solid #ddd;'><b>Blockers</b></td><td style='padding:8px;border-bottom:1px solid #ddd;'>${d.blockers || 'None'}</td></tr>
  <tr><td style='padding:8px;'><b>Next Steps</b></td><td style='padding:8px;'>${d.next_steps || 'N/A'}</td></tr>
</table>
<p style='color:#666;font-size:12px;'>Generated by Genome AI Agent System at ${now}</p>
</body></html>`;

// --- 4. CLIENT PDF HTML (rendered by Gotenberg) ---
// NOTE: Gotenberg is a free open-source Docker microservice that converts HTML→PDF.
// Deploy it on your server: docker run --rm -p 3000:3000 gotenberg/gotenberg:8
// Then set GOTENBERG_URL in n8n Variables.
const clientPdfHtml = `
<!DOCTYPE html><html><head>
<style>
  body{font-family:'Helvetica Neue',Arial,sans-serif;margin:0;padding:40px;color:#222;}
  .header{background:#1a1a2e;color:white;padding:24px 32px;margin:-40px -40px 32px;}
  .header h1{margin:0;font-size:22px;letter-spacing:1px;}
  .header p{margin:4px 0 0;font-size:12px;opacity:0.7;}
  .badge{display:inline-block;padding:4px 12px;border-radius:20px;font-size:13px;font-weight:bold;color:white;
    background:${ d.status === 'Completed' ? '#27ae60' : d.status === 'Blocked' ? '#e74c3c' : '#f39c12' };}
  .section{margin:24px 0;}
  .section h3{font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#888;margin-bottom:8px;}
  .progress-bar{background:#eee;border-radius:8px;height:12px;margin:8px 0;}
  .progress-fill{background:#1a1a2e;height:12px;border-radius:8px;width:${d.progress_pct || 0}%;}
  table{width:100%;border-collapse:collapse;}
  td{padding:10px 12px;border-bottom:1px solid #eee;font-size:14px;}
  td:first-child{color:#666;width:40%;}
  .footer{margin-top:40px;padding-top:16px;border-top:1px solid #eee;font-size:11px;color:#aaa;text-align:center;}
</style>
</head><body>
<div class='header'>
  <h1>🏗️ GENOME CORPORATION</h1>
  <p>Site Progress Report — ${new Date().toLocaleDateString('en-IN', {day:'2-digit',month:'long',year:'numeric'})}</p>
</div>

<div style='display:flex;justify-content:space-between;align-items:center;'>
  <div>
    <h2 style='margin:0;font-size:20px;'>Site: ${d.site_id || 'N/A'}</h2>
    <p style='margin:4px 0;color:#666;'>Phase: ${d.work_phase || 'N/A'}</p>
  </div>
  <div class='badge'>${statusEmoji} ${d.status}</div>
</div>

<div class='section'>
  <h3>Overall Progress</h3>
  <div style='font-size:28px;font-weight:bold;'>${d.progress_pct || 0}%</div>
  <div class='progress-bar'><div class='progress-fill'></div></div>
</div>

<div class='section'>
  <h3>Report Details</h3>
  <table>
    <tr><td>Work Completed Today</td><td>${d.raw_text || 'N/A'}</td></tr>
    <tr><td>Blockers / Issues</td><td>${d.blockers || 'None reported'}</td></tr>
    <tr><td>Next Actions</td><td>${d.next_steps || 'N/A'}</td></tr>
    <tr><td>Site Supervisor</td><td>${d.supervisor_name || 'N/A'}</td></tr>
    <tr><td>Report Generated</td><td>${now}</td></tr>
  </table>
</div>

<div class='footer'>This report was automatically generated by Genome AI Operations System. For queries contact your project manager.</div>
</body></html>`;

return [{ json: {
  ...d,
  supervisorAck,
  managerWhatsApp,
  rahulEmailSubject,
  rahulEmailBody,
  clientPdfHtml,
  supervisor_phone: d.supervisor_phone || d.from,
  manager_phone: d.manager_phone || $vars.PROJECT_MANAGER_PHONE,
  manager_email: d.manager_email || $vars.MANAGER_EMAIL,
  rahul_email: $vars.RAHUL_EMAIL || 'rahul.tanwar@genomecorporation.com',
  rahul_phone: $vars.RAHUL_PHONE || '',
  client_phone: d.client_phone || '',
  client_email: d.client_email || ''
}}];

# ============================================================
# Genome Corporation — Branded PDF Generator
# Uses reportlab (pre-installed on n8n self-hosted)
# For n8n cloud: use the HTTP Request approach described below
# ============================================================
# NOTE FOR n8n CLOUD USERS:
# n8n cloud Code nodes do NOT support Python or pip install.
# Two options:
#   OPTION A (Recommended): Deploy a tiny Flask microservice
#             on Railway/Render that accepts JSON and returns PDF.
#             See genome-pdf-service setup below.
#   OPTION B: Use the HTML-to-PDF approach via a self-hosted n8n.
#
# This node outputs the data payload needed for OPTION A.
# ============================================================

const d = $input.first().json;
const dateStr = new Date().toLocaleDateString('en-IN', {
  day: '2-digit', month: 'long', year: 'numeric'
});

// Package all data for the PDF microservice
const pdfPayload = {
  site_id: d.site_id || 'N/A',
  client_name: d.client_name || 'Valued Client',
  work_phase: d.work_phase || 'N/A',
  status: d.status || 'On Track',
  progress_pct: d.progress_pct || 0,
  supervisor_name: d.supervisor_name || 'N/A',
  raw_text: d.raw_text || 'No details provided',
  blockers: d.blockers || 'None',
  next_steps: d.next_steps || 'N/A',
  report_date: dateStr,
  parsed_at: d.parsed_at
};

const filename = `Genome-SiteReport-${d.site_id || 'unknown'}-${dateStr.replace(/ /g,'-')}.pdf`;

// WhatsApp message for client
const clientWhatsAppMsg = `📄 *Genome Corporation — Site Progress Report*

Dear ${d.client_name || 'Valued Client'},

Your site progress report for *${d.site_id || 'N/A'}* is ready.

📊 Status: ${d.status}
📈 Progress: ${d.progress_pct || 'N/A'}%

🔗 Report: DRIVE_URL_PLACEHOLDER

_${dateStr} | Genome AI Operations_`;

return [{ json: {
  ...d,
  pdf_payload: pdfPayload,
  pdf_filename: filename,
  clientWhatsAppMsg,
  pdf_service_url: $vars.PDF_SERVICE_URL || 'https://your-pdf-service.railway.app/generate'
}}];

const now = new Date();
const stale = $input.all()
  .map(i => i.json)
  .filter(site => {
    if (!site.last_updated || site.status === 'Completed') return false;
    const lastUpdate = new Date(site.last_updated);
    const hoursAgo = (now - lastUpdate) / (1000 * 60 * 60);
    return hoursAgo >= 48;
  });
if (stale.length === 0) return [{ json: { skipped: true, reason: 'No stale sites' } }];
return stale.map(s => ({ json: s }));

const driveFile = $input.first().json;
const prev = $('jsPDF: Generate PDF + Build Client Payload').first().json;
const fileId = driveFile.id;
const publicUrl = `https://drive.google.com/file/d/${fileId}/view?usp=sharing`;
const msg = prev.clientWhatsAppMsg.replace('DRIVE_URL_PLACEHOLDER', publicUrl);
return [{ json: { ...prev, pdf_public_url: publicUrl, pdf_file_id: fileId, clientWhatsAppMsg: msg } }];

