const raw = $input.first().json.message?.content || $input.first().json.content || '{}';
const prev = $('Build All Output Messages').first().json;

let polished;
try {
  polished = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  // Fallback: use original draft messages if Claude response fails to parse
  polished = {
    supervisor_ack: prev.supervisorAck,
    manager_whatsapp: prev.managerWhatsApp,
    rahul_email_body: prev.rahulEmailBody,
    client_whatsapp: prev.clientWhatsAppMsg
  };
}

return [{ json: {
  ...prev,
  supervisorAck: polished.supervisor_ack || prev.supervisorAck,
  managerWhatsApp: polished.manager_whatsapp || prev.managerWhatsApp,
  rahulEmailBody: polished.rahul_email_body || prev.rahulEmailBody,
  clientWhatsAppMsg: polished.client_whatsapp || prev.clientWhatsAppMsg,
  messages_polished: true
}}];
